  getSettingsOverview,listAcademicYears,listYearSelector,listClasses,listFeeTypes,listSchools,listSections,listTariffs,loginPlatform,loginSchool,
  putSection,ReferenceCatalog,School,SchoolClass,SchoolLoginResult,SchoolSection,SettingsOverview,Tariff,createTariff,updateSchoolIdentity,listSettingsContributions,createSettingsContribution,listSettingsProducts,createSettingsProduct,SettingsContribution,SettingsProduct,platformDashboard,platformSchoolsPage,platformAccess,platformAudit,platformDiagnostics,platformSuspendSchool,platformReactivateSchool,platformBootstrapAdmin,platformSystemNotifications,sendPlatformSystemNotification,platformSchoolDetail,platformRbacRoles,platformMembershipState,platformAssignRole,platformRevokeRole,platformGrantCollaborator,platformRevokeCollaborator
