const BLOCKING_LABEL:Record<string,string>={ENROLL_STUDENT:'les inscriptions',GENERATE_FEES:'la génération des frais',CONFIGURE_TARIFF:'la saisie des tarifs',SEND_SMS:'l’envoi de SMS'};
const PLATFORM_TOKEN='edusync.platform.token';
const SCHOOL_SESSION='edusync.school.session';

type SavedSchoolSession={token:string;school:SchoolLoginResult['school'];user:SchoolLoginResult['user'];permissions:string[]};

function AtelierPro({token,user,onLogout}:{token:string;user:PlatformUser;onLogout:()=>void}){
  const [tab,setTab]=useState<'dashboard'|'schools'|'access'|'notifications'|'audit'|'diagnostics'>('dashboard');
  useEffect(()=>{replaceMobileRoot('platform','dashboard');const h=(e:Event)=>{const d=(e as CustomEvent).detail;if(d?.edusyncScope==='platform'&&d.edusyncScreen)setTab(d.edusyncScreen)};window.addEventListener('edusync:android-back',h);return()=>window.removeEventListener('edusync:android-back',h)},[]);
  const goTab=(next:typeof tab)=>{if(next!==tab)pushMobileScreen('platform',next);setTab(next)};
  const [dashboard,setDashboard]=useState<any>(null),[schools,setSchools]=useState<any>({items:[]}),[access,setAccess]=useState<any>({items:[]}),[audit,setAudit]=useState<any>({items:[]}),[diag,setDiag]=useState<any>(null),[systemNotifications,setSystemNotifications]=useState<any>({items:[]});
  const [q,setQ]=useState(''),[status,setStatus]=useState(''),[accessQ,setAccessQ]=useState(''),[error,setError]=useState('');
  const [notificationOpen,setNotificationOpen]=useState(false);
  const [schoolAction,setSchoolAction]=useState<{kind:'suspend'|'reactivate'|'admin';school:any}|null>(null);
  const [schoolDetailId,setSchoolDetailId]=useState<string|null>(null);
  const [collaboratorAction,setCollaboratorAction]=useState<any|null>(null);
  const schoolSchema=z.object({name:z.string().trim().min(2,'Le nom de l’école est obligatoire.'),code:z.string().trim().min(2,'Le code établissement est obligatoire.').max(24,'Le code est trop long.')});type SchoolCreateForm=z.infer<typeof schoolSchema>;const schoolForm=useForm<SchoolCreateForm>({resolver:zodResolver(schoolSchema),defaultValues:{name:'',code:''},...formDefaults});
  async function refresh(){try{setError('');const [d,sc,ac,au,di]=await Promise.all([platformDashboard(token),platformSchoolsPage(token,q,status,0),platformAccess(token,accessQ,0),platformAudit(token),platformDiagnostics(token)]);setDashboard(d);setSchools(sc);setAccess(ac);setAudit(au);setDiag(di);try{setSystemNotifications(await platformSystemNotifications(token,0))}catch{/* permission absente ou migration non appliquée */}}catch(e){setError(friendlyError(e))}}
  useEffect(()=>{void refresh()},[token]);
  async function searchSchools(){try{setSchools(await platformSchoolsPage(token,q,status,0))}catch(e){setError(friendlyError(e))}}
  async function searchAccess(){try{setAccess(await platformAccess(token,accessQ,0))}catch(e){setError(friendlyError(e))}}
  const submit=schoolForm.handleSubmit(async values=>{try{await createSchool(token,{name:values.name.trim(),code:values.code.trim().toUpperCase()});schoolForm.reset();toast.success('École créée');await refresh()}catch(e){setError(friendlyError(e))}});
  const nav:any[]=[['cockpit','Tableau de bord',tab==='dashboard',()=>goTab('dashboard')],['school','Écoles',tab==='schools',()=>goTab('schools')],['lock','Accès',tab==='access',()=>goTab('access')],['bell','Notifications système',tab==='notifications',()=>goTab('notifications')],['audit','Journal d’audit',tab==='audit',()=>goTab('audit')],['pulse','État du service',tab==='diagnostics',()=>goTab('diagnostics')]];
  return <Shell title="Atelier Pro" subtitle="Pilotage et administration de la plateforme EduSync" onLogout={onLogout} nav={nav} user={user} token={token}>
    {error&&<div className="error">{error}</div>}
    {tab==='dashboard'&&<><div className="kpis"><Kpi icon="school" value={dashboard?.schools?.total??'—'} label="Écoles"/><Kpi icon="checkCircle" value={dashboard?.schools?.active??'—'} label="Actives"/><Kpi icon="users" value={dashboard?.active_memberships??'—'} label="Accès actifs"/><Kpi icon="sync" value={dashboard?.outbox_pending??'—'} label="Événements à diffuser"/></div><Panel title="Activité récente" subtitle="Derniers événements auditables de la plateforme et des écoles."><div className="dataTable"><div className="row platformAuditRow header"><span>Date</span><span>École</span><span>Action</span><span>Résultat</span></div>{(dashboard?.recent_activity??[]).map((x:any)=><div className="row platformAuditRow" key={x.id}><span>{new Date(x.occurred_at).toLocaleString()}</span><span>{x.school_code||'Plateforme'}</span><span><b title={x.action}>{auditActionLabel(x.action)}</b><small>{x.actor||'Système'}</small></span><span><em className={x.result==='SUCCESS'?'pill ready':'pill'}>{resultLabel(x.result)}</em></span></div>)}</div></Panel></>}
    {tab==='schools'&&<Panel title="Annuaire des écoles" subtitle="Création, statut, administrateur initial et actions de gouvernance, toutes tracées."><form className="inlineForm" onSubmit={e=>{e.preventDefault();void searchSchools()}}><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Rechercher nom ou code"/><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">Tous les statuts</option><option value="ACTIVE">Active</option><option value="SUSPENDED">Suspendue</option><option value="DISABLED">Désactivée</option></select><button>Rechercher</button></form><form className="inlineForm validatedInlineForm" onSubmit={submit} noValidate><FormField label="Nom *" error={schoolForm.formState.errors.name?.message}><input {...schoolForm.register('name')}/></FormField><FormField label="Code *" error={schoolForm.formState.errors.code?.message}><input {...schoolForm.register('code')}/></FormField><button disabled={schoolForm.formState.isSubmitting}>+ Créer</button></form><div className="dataTable"><div className="row platformSchoolActionRow header"><span>École</span><span>Statut</span><span>Accès</span><span>Admin initial</span><span>Actions</span></div>{schools.items.map((x:any)=><div className="row platformSchoolActionRow" key={x.id}><span><b>{x.name}</b><small>{x.code}</small></span><span><em className={x.status==='ACTIVE'?'pill ready':'pill'}>{schoolStatusLabel(x.status)}</em></span><span>{x.active_memberships}</span><span>{x.admin_count>0?'Configuré':'À créer'}</span><span className="rowActions"><button className="ghost" onClick={()=>setSchoolDetailId(x.id)}>Fiche</button>{x.admin_count===0&&<button className="ghost" onClick={()=>setSchoolAction({kind:'admin',school:x})}>Créer admin</button>}{x.status==='ACTIVE'?<button className="danger" onClick={()=>setSchoolAction({kind:'suspend',school:x})}>Suspendre</button>:x.status==='SUSPENDED'?<button onClick={()=>setSchoolAction({kind:'reactivate',school:x})}>Réactiver</button>:null}</span></div>)}</div>{schools.has_more&&<button className="ghost" onClick={async()=>{const n=await platformSchoolsPage(token,q,status,schools.offset+schools.limit);setSchools({...n,items:[...schools.items,...n.items]})}}>Charger plus</button>}</Panel>}
    {tab==='access'&&<Panel title="Accès et identités" subtitle="Comptes et rattachements aux écoles. Les droits métier sont gérés par rôle dans chaque école."><form className="inlineForm" onSubmit={e=>{e.preventDefault();void searchAccess()}}><input value={accessQ} onChange={e=>setAccessQ(e.target.value)} placeholder="Nom ou adresse e-mail"/><button>Rechercher</button></form><div className="dataTable"><div className="row platformAccessRow header"><span>Utilisateur</span><span>Type</span><span>Écoles</span><span>Statut</span></div>{access.items.map((x:any)=><div className="row platformAccessRow" key={x.id}><span><b>{x.full_name}</b><small>{x.email}</small></span><span>{x.collaborator_platform?'Collaborateur plateforme':x.is_platform_admin?'Manager système':'Compte école'}</span><span>{x.schools||'—'}</span><span><em className={x.active?'pill ready':'pill'}>{x.active?'Actif':'Désactivé'}</em>{access.can_manage_collaborators&&x.active&&<button className="ghost compactAction" onClick={()=>setCollaboratorAction(x)}>{x.collaborator_platform?'Retirer collaboration':'Donner accès plateforme'}</button>}</span></div>)}</div>{access.has_more&&<button className="ghost" onClick={async()=>{const n=await platformAccess(token,accessQ,access.offset+access.limit);setAccess({...n,items:[...access.items,...n.items]})}}>Charger plus</button>}</Panel>}
    {tab==='notifications'&&<Panel title="Notifications système" subtitle="Messages internes émis par le Manager système vers une école active ou toutes les écoles actives. Chaque diffusion est auditée."><div className="moduleToolbar"><button onClick={()=>setNotificationOpen(true)}>+ Nouvelle notification</button></div><div className="dataTable"><div className="row platformNotificationRow header"><span>Date</span><span>Cible</span><span>Message</span><span>Destinataires</span></div>{systemNotifications.items.map((x:any)=><div className="row platformNotificationRow" key={x.id}><span>{new Date(x.created_at).toLocaleString()}</span><span><em className={x.severity==='CRITICAL'?'pill danger':x.severity==='WARNING'?'pill':'pill ready'}>{severityLabel(x.severity)}</em><small>{x.target_scope==='ALL_ACTIVE_SCHOOLS'?'Toutes les écoles actives':x.target_school_code}</small></span><span><b>{x.title}</b><small>{x.body}</small></span><span>{x.recipient_count}</span></div>)}</div>{systemNotifications.has_more&&<button className="ghost" onClick={async()=>{const n=await platformSystemNotifications(token,systemNotifications.offset+systemNotifications.limit);setSystemNotifications({...n,items:[...systemNotifications.items,...n.items]})}}>Charger plus</button>}</Panel>}
    {tab==='audit'&&<Panel title="Journal d’audit" subtitle="Toutes les actions tracées, de la plus récente à la plus ancienne. Rien ne peut y être modifié."><div className="dataTable"><div className="row platformAuditRow header"><span>Date</span><span>École</span><span>Action</span><span>Résultat</span></div>{audit.items.map((x:any)=><div className="row platformAuditRow" key={x.id}><span>{new Date(x.occurred_at).toLocaleString()}</span><span>{x.school_code||'Plateforme'}</span><span><b title={x.action}>{auditActionLabel(x.action)}</b><small>{x.actor||x.entity_type}</small></span><span><em className={x.result==='SUCCESS'?'pill ready':'pill'}>{resultLabel(x.result)}</em></span></div>)}</div>{audit.has_more&&<button className="ghost" onClick={async()=>{const n=await platformAudit(token,audit.next_cursor);setAudit({...n,items:[...audit.items,...n.items]})}}>Charger plus</button>}</Panel>}
    {tab==='diagnostics'&&<><div className="kpis"><Kpi icon="database" value={diag?.database??'—'} label="Base de données"/><Kpi icon="sync" value={diag?.outbox_pending??'—'} label="Événements à diffuser"/><Kpi icon="alert" value={diag?.sync_conflicts??'—'} label="Conflits de synchronisation"/><Kpi icon="lock" value={diag?.global_lock?'Oui':'Non'} label="Blocage général"/></div><Panel title="État du service" subtitle="Informations de supervision ; elles ne bloquent jamais les écoles."><div className="diagnosticGrid"><p>Écoles actives <b>{diag?.active_schools??'—'}</b></p><p>Appareils connectés <b>{diag?.active_device_sessions??'—'}</b></p><p>SMS définitivement non envoyés <b>{diag?.dead_letter_deliveries??'—'}</b></p><p>Conflits de synchronisation <b>{diag?.sync_conflicts??'—'}</b></p></div><button onClick={()=>void refresh()}>Actualiser les diagnostics</button></Panel></>}
    {notificationOpen&&<PlatformNotificationDialog token={token} schools={schools.items} onClose={()=>setNotificationOpen(false)} onDone={async()=>{setNotificationOpen(false);setSystemNotifications(await platformSystemNotifications(token,0));await refresh()}}/>}
    {schoolDetailId&&<PlatformSchoolDetailDialog token={token} schoolId={schoolDetailId} onClose={()=>setSchoolDetailId(null)} onChanged={refresh}/>}
    {schoolAction&&<PlatformSchoolActionDialog token={token} action={schoolAction} onClose={()=>setSchoolAction(null)} onDone={async()=>{setSchoolAction(null);await refresh()}}/>}
  {collaboratorAction&&<PlatformCollaboratorDialog user={collaboratorAction} onClose={()=>setCollaboratorAction(null)} onConfirm={async(reason)=>{try{if(collaboratorAction.collaborator_platform)await platformRevokeCollaborator(token,collaboratorAction.id,reason);else await platformGrantCollaborator(token,collaboratorAction.id,reason);toast.success(collaboratorAction.collaborator_platform?'Collaboration retirée':'Collaborateur plateforme activé');setCollaboratorAction(null);await searchAccess()}catch(e){setError(friendlyError(e))}}}/>}
  </Shell>
}

function PlatformSchoolDetailDialog({token,schoolId,onClose,onChanged}:{token:string;schoolId:string;onClose:()=>void;onChanged:()=>Promise<void>}){
 const [data,setData]=useState<any>(null),[roles,setRoles]=useState<any[]>([]),[error,setError]=useState(''),[busy,setBusy]=useState('');
 async function load(){try{setError('');const [d,r]=await Promise.all([platformSchoolDetail(token,schoolId),platformRbacRoles(token)]);setData(d);setRoles(r)}catch(e){setError(friendlyError(e))}}
 useEffect(()=>{void load()},[schoolId]);
 async function toggle(m:any){const reason='Gouvernance accès Atelier Pro';try{setBusy(m.membership_id);await platformMembershipState(token,m.membership_id,!m.membership_active,reason);toast.success(m.membership_active?'Accès désactivé':'Accès réactivé');await load();await onChanged()}catch(e){setError(friendlyError(e))}finally{setBusy('')}}
 async function role(m:any,code:string){if(!code)return;try{setBusy(m.membership_id);await platformAssignRole(token,m.membership_id,code,'Attribution de rôle par le Manager système');toast.success('Rôle attribué');await load();await onChanged()}catch(e){setError(friendlyError(e))}finally{setBusy('')}}
 async function revoke(m:any,code:string){try{setBusy(m.membership_id);await platformRevokeRole(token,m.membership_id,code,'Retrait de rôle par le Manager système');toast.success('Rôle retiré');await load();await onChanged()}catch(e){setError(friendlyError(e))}finally{setBusy('')}}
 if(!data)return <div className="modalBackdrop"><div className="platformActionModal"><div className="modalHead"><h3>Fiche école</h3><button onClick={onClose}>×</button></div>{error||'Chargement…'}</div></div>;
 const gates=Object.entries(data.readiness) as [string,boolean][];const labels:any={school_identity:'Identité école',initial_admin:'Administrateur initial',academic_year:'Année scolaire',classes:'Classes',fee_catalog:'Catalogue des frais'};
 return <div className="modalBackdrop"><div className="platformActionModal platformSchoolDetail" role="dialog" aria-modal="true"><div className="modalHead"><div><h3>{data.school.name}</h3><p>{data.school.code} · {schoolStatusLabel(data.school.status)}</p></div><button onClick={onClose}>×</button></div>{error&&<div className="error">{error}</div>}<div className="summaryStrip"><span><b>{data.ready_count}/{data.total_gates}</b> étapes de mise en service</span><span><b>{data.memberships}</b> accès actifs</span></div><div className="diagnosticGrid">{gates.map(([k,v])=><p key={k}>{labels[k]||k} <em className={v?'pill ready':'pill'}>{v?'PRÊT':'À CONFIGURER'}</em></p>)}</div><h4>Accès de l’école</h4><div className="dataTable"><div className="row platformAccessRow header"><span>Utilisateur</span><span>Rôles</span><span>Rôle à attribuer</span><span>Accès</span></div>{data.users.map((m:any)=><div className="row platformAccessRow" key={m.membership_id}><span><b>{m.full_name}</b><small>{m.email}</small></span><span>{m.role_assignments?.length?<div className="roleChips">{m.role_assignments.map((r:any)=><button key={r.assignment_id} className="ghost" disabled={busy===m.membership_id} title="Retirer ce rôle" onClick={()=>void revoke(m,r.role_code)}>{r.role_label||r.role_code} ×</button>)}</div>:'Aucun rôle'}</span><span><select disabled={!m.membership_active||busy===m.membership_id} defaultValue="" onChange={e=>void role(m,e.target.value)}><option value="">Attribuer…</option>{roles.map(r=><option key={r.id} value={r.code}>{r.label}</option>)}</select></span><span><button className={m.membership_active?'danger':''} disabled={busy===m.membership_id} onClick={()=>void toggle(m)}>{m.membership_active?'Désactiver':'Réactiver'}</button></span></div>)}</div><div className="modalFooter"><button onClick={onClose}>Fermer</button></div></div></div>
}

function PlatformNotificationDialog({token,schools,onClose,onDone}:{token:string;schools:any[];onClose:()=>void;onDone:()=>Promise<void>}){
 const schema=z.object({title:z.string().trim().min(2,'Titre obligatoire').max(180),body:z.string().trim().min(2,'Message obligatoire').max(2000),severity:z.enum(['INFO','WARNING','CRITICAL']),target_scope:z.enum(['ALL_ACTIVE_SCHOOLS','SCHOOL']),target_school_id:z.string().optional()}).superRefine((v,c)=>{if(v.target_scope==='SCHOOL'&&!v.target_school_id)c.addIssue({code:'custom',path:['target_school_id'],message:'Choisissez une école active.'})});type F=z.infer<typeof schema>;const f=useForm<F>({resolver:zodResolver(schema),defaultValues:{title:'',body:'',severity:'INFO',target_scope:'ALL_ACTIVE_SCHOOLS',target_school_id:''},...formDefaults});const [error,setError]=useState('');const scope=f.watch('target_scope');const submit=f.handleSubmit(async v=>{try{setError('');const r=await sendPlatformSystemNotification(token,{title:v.title.trim(),body:v.body.trim(),severity:v.severity,target_scope:v.target_scope,target_school_id:v.target_scope==='SCHOOL'?v.target_school_id:null});toast.success(`Notification distribuée à ${r.recipient_count} destinataire(s)`);await onDone()}catch(e){setError(friendlyError(e))}});return <div className="wizardBackdrop"><form className="accountSecurityDialog platformNotificationDialog" onSubmit={submit} noValidate><div className="modalHead"><div><h3>Notification système</h3><p>Diffusion interne auditable. Aucun SMS ou WhatsApp n’est envoyé par cette action.</p></div><button type="button" onClick={onClose}>×</button></div><FormField label="Titre *" error={f.formState.errors.title?.message}><input {...f.register('title')}/></FormField><FormField label="Niveau *" error={f.formState.errors.severity?.message}><select {...f.register('severity')}><option value="INFO">Information</option><option value="WARNING">Avertissement</option><option value="CRITICAL">Critique</option></select></FormField><FormField label="Cible *" error={f.formState.errors.target_scope?.message}><select {...f.register('target_scope')}><option value="ALL_ACTIVE_SCHOOLS">Toutes les écoles actives</option><option value="SCHOOL">Une école</option></select></FormField>{scope==='SCHOOL'&&<FormField label="École active *" error={f.formState.errors.target_school_id?.message}><select {...f.register('target_school_id')}><option value="">Choisir…</option>{schools.filter(x=>x.status==='ACTIVE').map(x=><option key={x.id} value={x.id}>{x.name} · {x.code}</option>)}</select></FormField>}<FormField label="Message *" error={f.formState.errors.body?.message}><textarea rows={6} {...f.register('body')}/></FormField>{error&&<div className="loginFriendlyError" role="alert">{error}</div>}<div className="modalActions"><button type="button" className="ghost" onClick={onClose}>Annuler</button><button disabled={f.formState.isSubmitting}>{f.formState.isSubmitting?'Diffusion…':'Envoyer la notification'}</button></div></form></div>}

function PlatformSchoolActionDialog({token,action,onClose,onDone}:{token:string;action:{kind:'suspend'|'reactivate'|'admin';school:any};onClose:()=>void;onDone:()=>Promise<void>}){
 const [reason,setReason]=useState(''),[email,setEmail]=useState(''),[fullName,setFullName]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 async function execute(){try{setBusy(true);setError('');if(action.kind==='suspend'){if(reason.trim().length<3)throw new Error('Indiquez le motif de suspension.');await platformSuspendSchool(token,action.school.id,reason.trim());toast.success('École suspendue');}else if(action.kind==='reactivate'){await platformReactivateSchool(token,action.school.id);toast.success('École réactivée');}else{if(!email.trim()||fullName.trim().length<2||password.length<10)throw new Error('Nom, e-mail et mot de passe d’au moins 10 caractères sont obligatoires.');await platformBootstrapAdmin(token,action.school.id,{email:email.trim().toLowerCase(),full_name:fullName.trim(),password});toast.success('Administrateur initial créé');}await onDone()}catch(e){setError(friendlyError(e));setBusy(false)}}
 const title=action.kind==='suspend'?'Suspendre l’école':action.kind==='reactivate'?'Réactiver l’école':'Créer l’administrateur initial';
 return <div className="modalBackdrop" onMouseDown={e=>e.currentTarget===e.target&&onClose()}><div className="platformActionModal" role="dialog" aria-modal="true" aria-label={title}><div className="modalHead"><div><h3>{title}</h3><p><b>{action.school.name}</b> · {action.school.code}</p></div><button className="iconAction" onClick={onClose}>×</button></div>{error&&<div className="error">{error}</div>}{action.kind==='suspend'&&<label>Motif obligatoire<textarea value={reason} onChange={e=>setReason(e.target.value)} rows={4} placeholder="Motif administratif ou technique de la suspension"/></label>}{action.kind==='reactivate'&&<p>La réactivation rendra à nouveau l’école disponible selon ses accès et son état de préparation. L’opération sera auditée.</p>}{action.kind==='admin'&&<div className="platformAdminForm"><label>Nom complet<input value={fullName} onChange={e=>setFullName(e.target.value)} autoFocus/></label><label>Adresse e-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Mot de passe initial<input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="new-password"/><small>10 caractères minimum. Le mot de passe n’est jamais écrit dans l’audit ni dans la clé d’idempotence.</small></label></div>}<div className="modalFooter"><button className="ghost" onClick={onClose} disabled={busy}>Annuler</button><button className={action.kind==='suspend'?'danger':''} onClick={()=>void execute()} disabled={busy}>{busy?'Traitement…':action.kind==='suspend'?'Confirmer la suspension':action.kind==='reactivate'?'Réactiver':'Créer l’administrateur'}</button></div></div></div>
}

const parameterTabs=[
 ['checkCircle','Mise en service','overview'],['school','École & identité','identity'],['calendar','Années scolaires','years'],['layers','Structure & classes','structure'],['receipt','Types de frais','fees'],['tag','Tarifs & barèmes','tariffs'],['box','Contributions en nature','contributions'],['cart','Articles scolaires','products'],
] as const;

type TabKey=typeof parameterTabs[number][2];

function SettingsPage({session}:{session:SavedSchoolSession}){
  const token=session.token;const [tab,setTab]=useState<TabKey>('overview');const [overview,setOverview]=useState<SettingsOverview|null>(null);const [years,setYears]=useState<AcademicYear[]>([]);const [sections,setSections]=useState<SchoolSection[]>([]);const [classes,setClasses]=useState<SchoolClass[]>([]);const [fees,setFees]=useState<FeeType[]>([]);const [tariffs,setTariffs]=useState<Tariff[]>([]);const [contributions,setContributions]=useState<SettingsContribution[]>([]);const [products,setProducts]=useState<SettingsProduct[]>([]);const [refs,setRefs]=useState<ReferenceCatalog|null>(null);const [error,setError]=useState('');
  const can=(p:string)=>session.permissions.includes(p);
  async function refresh(){try{setError('');const safe=<T,>(allowed:boolean,load:()=>Promise<T>,fallback:T)=>allowed?load():Promise.resolve(fallback);const [o,y,s,c,f,t,co,p,r]=await Promise.all([safe(can('settings.school_identity.read'),()=>getSettingsOverview(token),null),safe(can('settings.academic_year.read'),()=>listAcademicYears(token),[]),safe(can('settings.structure.read'),()=>listSections(token),[]),safe(can('settings.structure.read'),()=>listClasses(token),[]),safe(can('settings.fee_types.read'),()=>listFeeTypes(token),[]),safe(can('settings.tariffs.read'),()=>listTariffs(token),[]),safe(can('settings.contributions.read'),()=>listSettingsContributions(token),[]),safe(can('settings.products.read'),()=>listSettingsProducts(token),[]),safe(can('settings.structure.read'),()=>getReferenceCatalog(token),null)]);setOverview(o);setYears(y);setSections(s);setClasses(c);setFees(f);setTariffs(t);setContributions(co);setProducts(p);setRefs(r)}catch(e){setError(friendlyError(e))}}
  useEffect(()=>{void refresh()},[token]);
  return <><div className="settingsHeader"><div><h2>Centre de configuration</h2><p>Paramétrage progressif : aucune configuration globale ne bloque EduSync.</p></div>{overview&&<div className="readinessBadge"><b>{overview.readiness.percent}%</b><span>Mise en service</span></div>}</div>{error&&<div className="error">{error}</div>}<div className="settingsLayout"><div className="settingsNav">{parameterTabs.filter(([, ,key])=>key==='overview'||key==='identity'?can('settings.school_identity.read'):key==='years'?can('settings.academic_year.read'):key==='structure'?can('settings.structure.read'):key==='fees'?can('settings.fee_types.read'):key==='tariffs'?can('settings.tariffs.read'):key==='contributions'?can('settings.contributions.read'):key==='products'?can('settings.products.read'):false).map(([icon,label,key])=><button key={key} className={tab===key?'active':''} aria-current={tab===key?'page':undefined} onClick={()=>setTab(key)}><span aria-hidden="true"><NavGlyph g={icon} size={17}/></span>{label}</button>)}</div><div className="settingsContent">
    {tab==='overview'&&<Readiness overview={overview}/>} {tab==='identity'&&<IdentitySettings token={token} overview={overview} can={can} onDone={refresh}/>} {tab==='years'&&<Years token={token} years={years} can={can} onDone={refresh}/>} {tab==='structure'&&<Structure token={token} sections={sections} classes={classes} years={years} refs={refs} can={can} onDone={refresh}/>} {tab==='fees'&&<Fees token={token} fees={fees} refs={refs} can={can} onDone={refresh}/>} {tab==='tariffs'&&<Tariffs token={token} tariffs={tariffs} years={years} fees={fees} classes={classes} can={can} onDone={refresh}/>} {tab==='contributions'&&<ContributionsSettings token={token} items={contributions} can={can} onDone={refresh}/>} {tab==='products'&&<ProductsSettings token={token} items={products} can={can} onDone={refresh}/>}
  </div></div></>
}

function Readiness({overview}:{overview:SettingsOverview|null}){if(!overview)return <Loading/>;return <Panel title="École immédiatement exploitable" subtitle="Le pourcentage est informatif. Seule l’action qui manque d’un prérequis est bloquée."><div className="readinessGrid">{overview.readiness.items.map(i=><div className="readinessItem" key={i.code}><em className={`status ${i.state.toLowerCase()}`}>{i.state==='READY'?'Prêt':i.state==='NOT_APPLICABLE'?'Non applicable':i.state==='TO_CONFIRM'?'À confirmer':'À compléter'}</em><b>{i.label}</b><p>{i.detail}</p>{i.blocking_only_for.length>0&&<small>Nécessaire pour : {i.blocking_only_for.map((c:string)=>BLOCKING_LABEL[c]??c.toLowerCase()).join(' · ')}</small>}</div>)}</div></Panel>}

function Years({token,years,can,onDone}:{token:string;years:AcademicYear[];can:(x:string)=>boolean;onDone:()=>Promise<void>}){
  const [error,setError]=useState('');const yearSchema=z.object({code:z.string().trim().min(4,'Le code est obligatoire.'),label:z.string().trim().min(4,'Le libellé est obligatoire.'),start_date:z.string().min(1,'La date de début est obligatoire.'),end_date:z.string().min(1,'La date de fin est obligatoire.')}).refine(v=>v.end_date>=v.start_date,{message:'La fin doit être postérieure au début.',path:['end_date']});type YearForm=z.infer<typeof yearSchema>;const yearForm=useForm<YearForm>({resolver:zodResolver(yearSchema),defaultValues:{code:'2026-2027',label:'2026-2027',start_date:'2026-09-01',end_date:'2027-06-30'},...formDefaults});
  const create=yearForm.handleSubmit(async form=>{try{await createAcademicYear(token,form);await onDone()}catch(e){setError(friendlyError(e))}});
  async function act(y:AcademicYear,action:'activate'|'close'|'archive'|'reopen'){try{if(action==='activate')await activateAcademicYear(token,y);else await transitionAcademicYear(token,y,action);await onDone()}catch(e){setError(friendlyError(e))}}
  return <Panel title="Années scolaires" subtitle="Une année est préparée, mise en cours, clôturée puis archivée. Une année rouverte repasse en préparation.">{can('settings.academic_year.create')&&<form className="gridForm validatedGridForm" onSubmit={create} noValidate><FormField label="Code *" error={yearForm.formState.errors.code?.message}><input {...yearForm.register('code')}/></FormField><FormField label="Libellé *" error={yearForm.formState.errors.label?.message}><input {...yearForm.register('label')}/></FormField><FormField label="Début *" error={yearForm.formState.errors.start_date?.message}><input type="date" {...yearForm.register('start_date')}/></FormField><FormField label="Fin *" error={yearForm.formState.errors.end_date?.message}><input type="date" {...yearForm.register('end_date')}/></FormField><button disabled={yearForm.formState.isSubmitting}>Préparer l’année</button></form>}{error&&<div className="error">{error}</div>}<div className="cardsList">{years.map(y=><article key={y.id}><div><b>{y.label}</b><small>{y.start_date} → {y.end_date}</small></div><em className={`pill ${y.status==='ACTIVE'?'ready':''}`}>{yearStatusLabel(y.status)}</em><div className="rowActions">{y.status==='PREPARED'&&can('settings.academic_year.activate')&&<button onClick={()=>void act(y,'activate')}>Activer</button>}{y.status==='ACTIVE'&&can('settings.academic_year.close')&&<button onClick={()=>void act(y,'close')}>Clôturer</button>}{y.status==='CLOSED'&&can('settings.academic_year.archive')&&<button onClick={()=>void act(y,'archive')}>Archiver</button>}{(y.status==='CLOSED'||y.status==='ARCHIVED')&&can('settings.academic_year.reopen')&&<button className="ghost" onClick={()=>void act(y,'reopen')}>Réouvrir</button>}</div></article>)}</div></Panel>
}

function Structure({token,sections,classes,years,refs,can,onDone}:{token:string;sections:SchoolSection[];classes:SchoolClass[];years:AcademicYear[];refs:ReferenceCatalog|null;can:(x:string)=>boolean;onDone:()=>Promise<void>}){
  const [error,setError]=useState('');const [sectionId,setSectionId]=useState('');const [referenceCode,setReferenceCode]=useState('');const active=years.find(y=>y.status==='ACTIVE')??years.find(y=>y.status==='PREPARED');
  async function addSection(code:string,label:string){try{await putSection(token,{code,label,enabled:true});await onDone()}catch(e){setError(friendlyError(e))}}
  async function addClass(){try{const section=sections.find(x=>x.id===sectionId);const ref=refs?.classes.find(x=>x.code===referenceCode);if(!active||!section||!ref)throw new Error('Choisissez une année, une section et une classe de référence');if(ref.section_code!==section.code)throw new Error('La classe de référence ne correspond pas à la section choisie');await createClass(token,{academic_year_id:active.id,section_id:section.id,reference_code:ref.code,code:ref.code,label:ref.label});setReferenceCode('');await onDone()}catch(e){setError(friendlyError(e))}}
  const existing=new Set(sections.map(s=>s.code));const classCodes=new Set(classes.filter(c=>c.academic_year_id===active?.id).map(c=>c.code));
  return <Panel title="Structure & classes" subtitle="Le référentiel RDC propose la structure, mais l’école confirme seulement ce qu’elle organise réellement.">{error&&<div className="error">{error}</div>}<div className="suggestions">{refs?.sections.map(r=><button disabled={existing.has(r.code)||!can('settings.sections.manage')} key={r.code} onClick={()=>void addSection(r.code,r.label)}>{existing.has(r.code)?'✓ ': '+ '}{r.label}</button>)}</div><div className="cardsList">{sections.map(s=><article key={s.id}><div><b>{s.label}</b><small>{s.code}</small></div><em className="pill ready">Active</em></article>)}</div>{can('settings.classes.create')&&active&&sections.length>0&&<div className="gridForm"><select aria-label="Section" value={sectionId} onChange={e=>setSectionId(e.target.value)}><option value="">Section…</option>{sections.filter(s=>s.enabled).map(s=><option key={s.id} value={s.id}>{s.label}</option>)}</select><select aria-label="Classe de référence" value={referenceCode} onChange={e=>setReferenceCode(e.target.value)}><option value="">Classe de référence…</option>{refs?.classes.filter(r=>!classCodes.has(r.code)).map(r=><option key={r.code} value={r.code}>{r.label}</option>)}</select><button type="button" onClick={()=>void addClass()}>Ouvrir la classe</button></div>}<div className="dataTable"><div className="row header"><span>Classe</span><span>Section</span><span>Année</span><span>Statut</span></div>{classes.map(c=><div className="row" key={c.id}><span><b>{c.label}</b><small>{c.code}</small></span><span>{c.section_label??c.section_code}</span><span>{c.academic_year_code}</span><span><em className={`pill ${c.enabled?'ready':''}`}>{c.enabled?'Active':'Inactive'}</em></span></div>)}</div></Panel>
}

function Fees({token,fees,refs,can,onDone}:{token:string;fees:FeeType[];refs:ReferenceCatalog|null;can:(x:string)=>boolean;onDone:()=>Promise<void>}){const [error,setError]=useState('');const existing=new Set(fees.map(f=>f.code));async function add(f:ReferenceCatalog['fee_types'][number]){try{await createFeeType(token,{code:f.code,label:f.label,periodicity:f.periodicity,default_currency:f.default_currency});await onDone()}catch(e){setError(friendlyError(e))}}return <Panel title="Types de frais" subtitle="Le catalogue de référence n’engendre aucune dette tant qu’un tarif réel n’est pas confirmé.">{error&&<div className="error">{error}</div>}<div className="suggestions">{refs?.fee_types.map(f=><button key={f.code} disabled={existing.has(f.code)||!can('settings.fee_types.manage')} onClick={()=>void add(f)}>{existing.has(f.code)?'✓ ': '+ '}{f.label}</button>)}</div><div className="cardsList">{fees.map(f=><article key={f.id}><div><b>{f.label}</b><small>{f.periodicity} · {f.default_currency}</small></div><em className="pill ready">Actif</em></article>)}</div></Panel>}

function IdentitySettings({token,overview,can,onDone}:{token:string;overview:SettingsOverview|null;can:(x:string)=>boolean;onDone:()=>Promise<void>}){const school=overview?.school;const schema=z.object({name:z.string().trim().min(2,'Nom obligatoire.'),email:z.string().trim().email('E-mail invalide.').or(z.literal('')),phone:z.string(),logo_url:z.string(),address:z.string(),city:z.string(),province:z.string()});type F=z.infer<typeof schema>;const form=useForm<F>({resolver:zodResolver(schema),values:{name:school?.name??'',email:school?.email??'',phone:school?.phone??'',logo_url:school?.logo_url??'',address:school?.address??'',city:school?.city??'',province:school?.province??''},...formDefaults});const [error,setError]=useState('');const save=form.handleSubmit(async v=>{if(!school)return;try{setError('');await updateSchoolIdentity(token,{name:v.name,email:v.email||null,phone:v.phone||null,logo_url:v.logo_url||null,address:v.address||null,city:v.city||null,province:v.province||null},school.version);toast.success('Identité de l’école enregistrée');await onDone()}catch(e){setError(friendlyError(e))}});return <Panel title="École & identité" subtitle="Coordonnées institutionnelles utilisées par l’interface et les documents.">{error&&<div className="error">{error}</div>}<form className="settingsEditorGrid" onSubmit={save}><FormField label="Nom de l’école *" error={form.formState.errors.name?.message}><input {...form.register('name')}/></FormField><FormField label="Téléphone"><input {...form.register('phone')}/></FormField><FormField label="E-mail" error={form.formState.errors.email?.message}><input type="email" {...form.register('email')}/></FormField><FormField label="Ville"><input {...form.register('city')}/></FormField><FormField label="Province"><input {...form.register('province')}/></FormField><FormField label="Adresse"><input {...form.register('address')}/></FormField><FormField label="URL du logo"><input {...form.register('logo_url')}/></FormField>{can('settings.school_identity.update')&&<button className="primaryBtn" disabled={form.formState.isSubmitting}>Enregistrer</button>}</form></Panel>}

function Tariffs({token,tariffs,years,fees,classes,can,onDone}:{token:string;tariffs:Tariff[];years:AcademicYear[];fees:FeeType[];classes:SchoolClass[];can:(x:string)=>boolean;onDone:()=>Promise<void>}){const active=years.find(y=>y.status==='ACTIVE')??years.find(y=>y.status==='PREPARED');const schema=z.object({fee_type_id:z.string().min(1,'Frais obligatoire.'),currency:z.enum(['CDF','USD']),amount:z.string().refine(v=>Number(v)>0,'Montant positif obligatoire.'),class_id:z.string()});type F=z.infer<typeof schema>;const form=useForm<F>({resolver:zodResolver(schema),defaultValues:{fee_type_id:'',currency:'CDF',amount:'',class_id:''},...formDefaults});const [error,setError]=useState('');const save=form.handleSubmit(async v=>{if(!active)return;try{setError('');await createTariff(token,{academic_year_id:active.id,fee_type_id:v.fee_type_id,currency:v.currency,amount:v.amount,class_id:v.class_id||null,billing_months:[]});form.reset();toast.success('Tarif créé');await onDone()}catch(e){setError(friendlyError(e))}});return <Panel title="Tarifs & barèmes" subtitle="Un tarif réel est rattaché à une année et peut être ciblé sur une classe.">{error&&<div className="error">{error}</div>}{can('settings.tariffs.manage')&&active&&<form className="settingsEditorGrid compact" onSubmit={save}><FormField label="Type de frais *" error={form.formState.errors.fee_type_id?.message}><select {...form.register('fee_type_id')}><option value="">Choisir…</option>{fees.filter(f=>f.enabled!==false).map(f=><option key={f.id} value={f.id}>{f.label}</option>)}</select></FormField><FormField label="Classe (optionnel)"><select {...form.register('class_id')}><option value="">Toute l’école</option>{classes.filter(c=>c.academic_year_id===active.id&&c.enabled).map(c=><option key={c.id} value={c.id}>{c.label}</option>)}</select></FormField><FormField label="Devise"><select {...form.register('currency')}><option>CDF</option><option>USD</option></select></FormField><FormField label="Montant *" error={form.formState.errors.amount?.message}><input inputMode="decimal" {...form.register('amount')}/></FormField><button className="primaryBtn">Ajouter</button></form>}<div className="dataTable"><div className="row tariff header"><span>Frais</span><span>Périmètre</span><span>Montant</span><span>État</span></div>{tariffs.map(t=><div className="row tariff" key={t.id}><span>{fees.find(f=>f.id===t.fee_type_id)?.label??t.fee_type_id}</span><span>{t.class_id?classes.find(c=>c.id===t.class_id)?.label??'Classe':'École'}</span><span><b>{t.amount} {t.currency}</b></span><span><em className="pill ready">Actif</em></span></div>)}</div></Panel>}

function ContributionsSettings({token,items,can,onDone}:{token:string;items:SettingsContribution[];can:(x:string)=>boolean;onDone:()=>Promise<void>}){const schema=z.object({code:z.string().trim().min(2),label:z.string().trim().min(2),unit:z.string().trim().min(1)});type F=z.infer<typeof schema>;const form=useForm<F>({resolver:zodResolver(schema),defaultValues:{code:'',label:'',unit:'unité'},...formDefaults});const save=form.handleSubmit(async v=>{await createSettingsContribution(token,v);form.reset({code:'',label:'',unit:'unité'});toast.success('Contribution créée');await onDone()});return <Panel title="Contributions en nature" subtitle="Catalogue des fournitures ou biens attendus; les dépôts réels restent dans Effectifs & dépôts.">{can('settings.contributions.manage')&&<form className="settingsEditorGrid compact" onSubmit={save}><FormField label="Code"><input {...form.register('code')}/></FormField><FormField label="Libellé"><input {...form.register('label')}/></FormField><FormField label="Unité"><input {...form.register('unit')}/></FormField><button className="primaryBtn">Ajouter</button></form>}<div className="cardsList">{items.map(x=><article key={x.id}><div><b>{x.label}</b><small>{x.code} · {x.unit}</small></div><em className={`pill ${x.enabled?'ready':''}`}>{x.enabled?'Actif':'Inactif'}</em></article>)}</div></Panel>}

function ProductsSettings({token,items,can,onDone}:{token:string;items:SettingsProduct[];can:(x:string)=>boolean;onDone:()=>Promise<void>}){const schema=z.object({code:z.string().trim().min(2),label:z.string().trim().min(2),currency:z.enum(['CDF','USD']),unit_price:z.string().refine(v=>Number(v)>0),stock_tracking:z.boolean()});type F=z.infer<typeof schema>;const form=useForm<F>({resolver:zodResolver(schema),defaultValues:{code:'',label:'',currency:'CDF',unit_price:'',stock_tracking:true},...formDefaults});const save=form.handleSubmit(async v=>{await createSettingsProduct(token,v);form.reset({code:'',label:'',currency:'CDF',unit_price:'',stock_tracking:true});toast.success('Article créé');await onDone()});return <Panel title="Articles scolaires" subtitle="Catalogue utilisé par la vente d’articles; le suivi de stock reste relié à l’Intendance.">{can('settings.products.manage')&&<form className="settingsEditorGrid compact" onSubmit={save}><FormField label="Code"><input {...form.register('code')}/></FormField><FormField label="Article"><input {...form.register('label')}/></FormField><FormField label="Devise"><select {...form.register('currency')}><option>CDF</option><option>USD</option></select></FormField><FormField label="Prix"><input inputMode="decimal" {...form.register('unit_price')}/></FormField><label className="checkField"><input type="checkbox" {...form.register('stock_tracking')}/> Suivre le stock</label><button className="primaryBtn">Ajouter</button></form>}<div className="cardsList">{items.map(x=><article key={x.id}><div><b>{x.label}</b><small>{x.code} · {x.unit_price} {x.currency}{x.stock_tracking?' · stock suivi':''}</small></div><em className={`pill ${x.enabled?'ready':''}`}>{x.enabled?'Actif':'Inactif'}</em></article>)}</div></Panel>}

function ModuleLoader(){return <div className="moduleLoader"><div className="loaderLine"><i/></div><b>Ouverture du module…</b><span>Préparation de votre espace de travail</span></div>}
function Loading(){return <ModuleLoader/>}
function Kpi({icon,value,label}:{icon:string;value:React.ReactNode;label:string}){return <article><span aria-hidden="true"><NavGlyph g={icon} size={20}/></span><b>{value}</b><small>{label}</small></article>}
function Panel({title,subtitle,children}:{title:string;subtitle?:string;children:React.ReactNode}){return <section className="panel"><div className="panelHead"><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div></div>{children}</section>}
function PlatformCollaboratorDialog({user,onClose,onConfirm}:{user:any;onClose:()=>void;onConfirm:(reason:string)=>Promise<void>}){const [reason,setReason]=useState('');const [busy,setBusy]=useState(false);const revoke=Boolean(user.collaborator_platform);return <div className="modalBackdrop" onMouseDown={e=>e.currentTarget===e.target&&onClose()}><section className="platformActionModal" role="dialog" aria-modal="true" aria-label="Collaboration plateforme"><div className="modalHead"><div><h3>{revoke?'Retirer la collaboration':'Donner un accès collaborateur'}</h3><p>{user.full_name} · {user.email}</p></div><button className="ghost" onClick={onClose}>×</button></div><p className="collaboratorDoctrine">Le Collaborateur plateforme peut consulter les écoles, l’audit et les diagnostics. Il ne peut ni créer/suspendre une école, ni créer un administrateur, ni gérer d’autres collaborateurs.</p><label>Motif *<textarea value={reason} onChange={e=>setReason(e.target.value)} rows={3}/></label><div className="modalActions"><button className="ghost" onClick={onClose}>Annuler</button><button disabled={busy||reason.trim().length<5} onClick={async()=>{setBusy(true);try{await onConfirm(reason.trim())}finally{setBusy(false)}}}>{revoke?'Retirer':'Accorder'}</button></div></section></div>}

type PlatformUser={full_name:string;email:string};
function Shell({title,subtitle,onLogout,nav,children,user,token}:{title:string;subtitle:string;token?:string;onLogout:()=>void;nav:[string,string,boolean,(()=>void)?][];children:React.ReactNode;user:PlatformUser}){const [profile,setProfile]=useState(false);const [security,setSecurity]=useState(false);const keys=['dashboard','schools','access','notifications','audit','diagnostics'];const shellNav:ShellNavItem[]=nav.map(([icon,label,active,go],i)=>({key:keys[i]||label,label,icon,active,onSelect:()=>go?.(),primary:i<3,shortLabel:label.split(' ')[0]}));const account:ShellAccount={name:user.full_name||'Manager système',email:user.email,context:'Atelier Pro · Manager système',items:[{key:'profile',label:'Mon profil',icon:'user',onSelect:()=>setProfile(true)},{key:'security',label:'Sécurité et appareils',icon:'shield',onSelect:()=>setSecurity(true)},{key:'logout',label:'Se déconnecter',icon:'logout',onSelect:onLogout,danger:true}]};return <AppShell orgLabel="Atelier Pro" orgCode="Administration de la plateforme" mobileTitle="Atelier Pro" nav={shellNav} title={nav.find(n=>n[2])?.[1]||title} context={subtitle} tools={<StatusChip/>} account={account}>{children}{profile&&<ProfileDialog name={account.name} email={user.email} context="Atelier Pro · Manager système" onClose={()=>setProfile(false)}/>}{security&&token&&<SecurityDialog platform token={token} onClose={()=>setSecurity(false)} onPasswordChanged={onLogout}/>}</AppShell>}

// POINT 4D frozen navigation contract: ['settings','personnel','students','headcounts','home']
function SchoolApp({session,onLogout}:{session:SavedSchoolSession;onLogout:()=>void}){const [dialog,setDialog]=useState<''|'profile'|'security'>('');const [module,setModule]=useState('home');const goModule=(next:string)=>{if(next!==module)pushMobileScreen('school',next);setModule(next)};useEffect(()=>{replaceMobileRoot('school','home');const h=(e:Event)=>{const d=(e as CustomEvent).detail;if(d?.edusyncScope==='school'&&d.edusyncScreen)setModule(d.edusyncScreen)};window.addEventListener('edusync:android-back',h);return()=>window.removeEventListener('edusync:android-back',h)},[]);const [shellYears,setShellYears]=useState<AcademicYear[]>([]);const [selectedYearId,setSelectedYearId]=useState('');useEffect(()=>{let alive=true;listYearSelector(session.token).then(years=>{if(!alive)return;setShellYears(years);const saved=localStorage.getItem(`edusync.year.${session.school.id}`);const selected=(saved&&years.some(y=>y.id===saved)?saved:years.find(y=>y.status==='ACTIVE')?.id)||years[0]?.id||'';setSelectedYearId(selected)}).catch(()=>{if(alive)setShellYears([])});return()=>{alive=false}},[session.token,session.school.id]);function selectShellYear(id:string){setSelectedYearId(id);if(id)localStorage.setItem(`edusync.year.${session.school.id}`,id)}const selectedYear=shellYears.find(y=>y.id===selectedYearId);
  const nav=[['home','Accueil','home'],['settings','Paramètres','settings'],['users','Personnel','personnel'],['students','Élèves & inscriptions','students'],['chart','Effectifs & dépôts','headcounts'],['finance','Centre financier','finance'],['folder','Documents','documents'],['box','Intendance','stewardship'],['sync','Synchronisation','sync'],['lock','Accès & rôles','access']] as const;
  const prefixes:Record<string,string[]>={settings:['settings.'],personnel:['personnel.'],students:['students.','families.','enrollments.'],headcounts:['headcounts.'],finance:['finance.','contributions.'],documents:['documents.','students.directory.','families.directory.','personnel.directory.','headcounts.export','headcounts.print','finance.views.','finance.reports.'],stewardship:['inventory.'],sync:['sync.'],access:['access.roles.read','audit.school.read']};
  const canOpenModule=(key:string)=>key==='home'||(prefixes[key]??[]).some(prefix=>session.permissions.some(p=>p.startsWith(prefix)));
  const visibleNav=nav.filter(([, ,key])=>canOpenModule(key));
  const currentLabel=visibleNav.find(([, ,key])=>key===module)?.[1]||'EduSync';
  const shortLabels:Record<string,string>={home:'Accueil',students:'Élèves',finance:'Finance',documents:'Documents'};
  const shellNav:ShellNavItem[]=visibleNav.map(([icon,label,key])=>({key,label,icon,active:module===key,onSelect:()=>goModule(key),primary:['home','students','finance','documents'].includes(key),shortLabel:shortLabels[key]}));
  const yearLabel=selectedYear?.label;
  const account:ShellAccount={name:session.user.full_name,email:session.user.email,context:`${session.school.name} · ${session.school.code}`,detail:yearLabel?(/^ann[ée]e/i.test(yearLabel)?yearLabel:`Année ${yearLabel}`):undefined,items:[
    {key:'profile',label:'Mon profil',icon:'user',onSelect:()=>setDialog('profile')},
    ...(canOpenModule('settings')?[{key:'settings',label:'Paramètres de l’école',icon:'settings',onSelect:()=>goModule('settings')}]:[]),
    {key:'security',label:'Sécurité et appareils',icon:'shield',onSelect:()=>setDialog('security')},
    {key:'logout',label:'Se déconnecter',icon:'logout',onSelect:onLogout,danger:true}]};
  const yearSelect=(where:string)=>shellYears.length>0&&<label className={`es-year es-year-${where}`} title="Année scolaire consultée"><NavGlyph g="calendar" size={15}/><span>Année</span><select aria-label="Année scolaire consultée" value={selectedYearId} onChange={e=>selectShellYear(e.target.value)}>{shellYears.map(y=><option key={y.id} value={y.id} title={y.status==='ACTIVE'?'Année en cours':y.status==='CLOSED'?'Année clôturée':undefined}>{y.code||y.label}</option>)}</select></label>;
  const tools=<>{yearSelect('top')}<StatusChip compact={false}/>{session.permissions.includes('notifications.internal.read')&&<NotificationBell token={session.token} canDismiss={session.permissions.includes('notifications.internal.dismiss')}/>}</>;
  return <AppShell orgLabel={session.school.name} orgCode={session.school.code} drawerTools={yearSelect('drawer')} nav={shellNav} title={currentLabel} context={`${session.school.name}${yearLabel?` · ${yearLabel}`:''}`} tools={tools} account={account}>
    <Suspense fallback={<ModuleLoader/>}>{module==='settings'?<SettingsPage session={session}/>:module==='personnel'?<PersonnelPage token={session.token} permissions={session.permissions} schoolName={session.school.name}/>:module==='students'?<SchoolingPage token={session.token} permissions={session.permissions} schoolName={session.school.name}/>:module==='headcounts'?<EffectifsPage token={session.token} permissions={session.permissions} schoolName={session.school.name} yearId={selectedYearId||undefined}/>:module==='finance'?<FinancePage token={session.token} permissions={session.permissions}/>:module==='documents'?<DocumentsPage token={session.token} permissions={session.permissions} schoolName={session.school.name}/>:module==='stewardship'?<StewardshipPage token={session.token} permissions={session.permissions}/>:module==='sync'?<SyncAdminPage token={session.token} permissions={session.permissions}/>:module==='access'?<AccessPage token={session.token} permissions={session.permissions} userName={session.user.full_name}/>:module==='home'?<HomePage token={session.token} permissions={session.permissions} schoolName={session.school.name} userName={session.user.full_name} onNavigate={goModule} yearId={selectedYearId||undefined} yearLabel={selectedYear?.label}/>:<Panel title="Module" subtitle="Ce module sera activé lorsqu’il disposera de ses contrats métier certifiés."><div/></Panel>}</Suspense>
    {dialog==='profile'&&<ProfileDialog name={session.user.full_name} email={session.user.email} context={`${session.school.name} · ${session.school.code}`} detail={yearLabel} onClose={()=>setDialog('')}/>}
    {dialog==='security'&&<SecurityDialog token={session.token} onClose={()=>setDialog('')} onPasswordChanged={onLogout}/>}
  </AppShell>}

export function App(){
  useEffect(()=>{const offBack=installMobileBackCoordinator();const offDirty=installUnsavedFormGuard();return()=>{offBack();offDirty()}},[]);
  const [platformToken,setPlatformToken]=useState('');
  const [platformUser,setPlatformUser]=useState<PlatformUser>({full_name:'',email:''});
  const [schoolSession,setSchoolSession]=useState<SavedSchoolSession|null>(null);
  const [restoring,setRestoring]=useState(true);
  useEffect(()=>{let alive=true;(async()=>{try{const r=await fetch('/api/v1/auth/refresh',{method:'POST',credentials:'include',cache:'no-store'});if(!r.ok)return;const d=await r.json();if(!alive||!d.access_token)return;if(d.scope==='SCHOOL'&&d.school&&d.user){setSchoolSession({token:d.access_token,school:d.school,user:d.user,permissions:d.permissions||[]})}else if(d.scope==='PLATFORM'){setPlatformToken(d.access_token);if(d.user)setPlatformUser({full_name:d.user.full_name,email:d.user.email})}}catch{/* aucune session persistante : afficher la connexion */}finally{if(alive)setRestoring(false)}})();return()=>{alive=false}},[]);
  useEffect(()=>{const h=(e:Event)=>{const d=(e as CustomEvent).detail||{};if(!d.token)return;if(d.scope==='SCHOOL')setSchoolSession(prev=>prev?{...prev,token:d.token}:prev);else setPlatformToken(d.token)};window.addEventListener('edusync:token-refreshed',h);return()=>window.removeEventListener('edusync:token-refreshed',h)},[]);
  function clear(){void fetch('/api/v1/auth/logout',{method:'POST',credentials:'include'}).catch(()=>{});localStorage.removeItem(PLATFORM_TOKEN);localStorage.removeItem(SCHOOL_SESSION);setPlatformToken('');setSchoolSession(null)}
  useEffect(()=>{if(!restoring)dismissBoot()},[restoring]);
  // While the persistent session is checked, the static boot screen (index.html) stays on screen: one continuous start.
  if(restoring)return null;
  if(schoolSession)return <SchoolApp session={schoolSession} onLogout={clear}/>;
  if(platformToken)return <AtelierPro token={platformToken} user={platformUser} onLogout={clear}/>;
  return <SecureLogin onPlatform={(token,user)=>{setPlatformUser(user);setPlatformToken(token)}} onSchool={setSchoolSession}/>;
}
